// parsePreInvocation handles the PreInvocation hook → TurnStart.
// PreInvocation fires before each agent invocation. We always emit TurnStart;
// the framework's strategy.InitializeSession is idempotent on first arrival.
//
// On the very first invocation of a conversation (invocationNum=1) we also
// emit a "tracked by entire" banner via Antigravity's injectSteps/ephemeralMessage
// mechanism on stdout — see firstInvocationBannerJSON.
func parsePreInvocation(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[InvocationPayload](stdin)
	if err != nil {
		return nil, err
	}
	if banner := firstInvocationBannerJSON(raw.InvocationNum); banner != "" {
		// Best-effort: a write failure here would only mean the banner doesn't
		// appear — we still want to return the TurnStart event so session
		// state gets initialized.
		_, _ = fmt.Fprintln(os.Stdout, banner)
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.ConversationID,
		SessionRef: raw.TranscriptPath,
		Timestamp:  time.Now(),
	}, nil
}

func TestFirstInvocationBannerJSON(t *testing.T) {
	t.Parallel()
	if got := firstInvocationBannerJSON(0); got != "" {
		t.Errorf("invocationNum=0 should not emit a banner; got %q", got)
	}
	if got := firstInvocationBannerJSON(2); got != "" {
		t.Errorf("invocationNum=2 should not emit a banner; got %q", got)
	}
	got := firstInvocationBannerJSON(1)
	if got == "" {
		t.Fatal("invocationNum=1 should emit a banner")
	}
	var parsed PreInvocationOutput
	if err := json.Unmarshal([]byte(got), &parsed); err != nil {
		t.Fatalf("banner JSON should parse as PreInvocationOutput: %v\nraw: %s", err, got)
	}
	if len(parsed.InjectSteps) != 1 || parsed.InjectSteps[0].EphemeralMessage == "" {
		t.Errorf("banner should have exactly one InjectStep with non-empty ephemeralMessage; got %+v", parsed)
	}
}

