// firstInvocationBannerJSON returns Antigravity's injectSteps JSON payload
// (per /tmp/ag-hooks.md) that surfaces a "tracked by entire" ephemeral message
// in the agy UI on the user's first model invocation of a conversation.
// Returns "" when not the first invocation (no banner needed).
//
// Antigravity has no SessionStart hook surface, so we cannot route the banner
// through the framework's handleLifecycleSessionStart. Instead we use
// Antigravity's own injectSteps mechanism — which displays a transient message
// inline in the agy conversation — by writing the JSON to stdout from the
// PreInvocation hook. This is what the docs prescribe for PreInvocation output
// and what agy honors natively.
func firstInvocationBannerJSON(invocationNum int) string {
	if invocationNum != 1 {
		return ""
	}
	msg := InvocationOutput{
		InjectSteps: []InjectStep{
			{EphemeralMessage: "✓ Session tracked by entire"},
		},
	}
	b, err := json.Marshal(msg)
	if err != nil {
		return ""
	}
	return string(b)
}

