func TestResolveAgySymlinks_ParentSymlink(t *testing.T) {
	t.Parallel()
	// Set up a directory and a symlink that points to it
	realDir := t.TempDir()
	linkDir := filepath.Join(t.TempDir(), "link")
	if err := os.Symlink(realDir, linkDir); err != nil {
