	through := filepath.Join(linkDir, "new.txt")
	resolved := resolveAgySymlinks(through)
	want := filepath.Join(realDir, "new.txt")
	if resolved != want {
		t.Errorf("resolveAgySymlinks(%q) = %q, want %q", through, resolved, want)
	}
}

